contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmt, uint minSum, uint am, uint extra) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(depositAmt < minSum);
        require(am >= 0);
        require(extra <= type(uint256).max - depositAmt);

        // Setup: contract starts uninitialized, so SetMinSum works.
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalBefore = address(c).balance;

        // Deciding call: balance (depositAmt) is strictly below MinSum.
        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(
            !reverted
            && c.balances(address(this)) == balBefore
            && address(c).balance == contractBalBefore
        );
    }

    receive() external payable {}
}

