pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 depositAmt, uint256 minSum, uint256 am, uint256 extra) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmt < minSum);
        vm.assume(am >= 0);
        vm.assume(extra <= type(uint256).max - depositAmt);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint contractBalBefore = address(c).balance;
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted
            && c.balances(address(this)) == balBefore
            && address(c).balance == contractBalBefore);
    }

    function testFuzz_run(uint256 depositAmt, uint256 minSum, uint256 am, uint256 extra) public {
        _run(depositAmt, minSum, am, extra);
    }

    receive() external payable {}
}
